CREATE DATABASE IF NOT EXISTS StreamingDB;
USE StreamingDB;

CREATE TABLE Users (
        user_id INT PRIMARY KEY,
        username VARCHAR(50),
        email VARCHAR(100),
        gender VARCHAR(10),
        dob DATE,
        signup_date DATE);

CREATE TABLE Movies (
        movie_id INT PRIMARY KEY,
        title VARCHAR(200),
        genre VARCHAR(50),
        duration INT,
        release_year INT);

CREATE TABLE Subscriptions (
        sub_id INT PRIMARY KEY,
        user_id INT,
        plan_type VARCHAR(20),
        price DECIMAL(10,2),
        start_date DATE,
        end_date DATE,
        FOREIGN KEY (user_id) REFERENCES Users(user_id));

CREATE TABLE Reviews (
        review_id INT PRIMARY KEY,
        movie_id INT,
        user_id INT,
        rating INT,
        review_text TEXT,
        review_date DATE,
        FOREIGN KEY (movie_id) REFERENCES Movies(movie_id),
        FOREIGN KEY (user_id) REFERENCES Users(user_id));

CREATE TABLE WatchHistory (
        watch_id INT PRIMARY KEY,
        user_id INT,
        movie_id INT,
        watch_date DATETIME,
        watch_duration INT,
        FOREIGN KEY (user_id) REFERENCES Users(user_id),
        FOREIGN KEY (movie_id) REFERENCES Movies(movie_id));

CREATE TABLE Revenue (
        payment_id INT PRIMARY KEY,
        user_id INT,
        amount DECIMAL(10,2),
        payment_date DATE,
        method VARCHAR(20),
        FOREIGN KEY (user_id) REFERENCES Users(user_id));

