USE streamingdb;

-- Problem Statement: 
-- Analyze user watch history, subscriptions, and ratings to identify popular content, customer 
-- churn risk, and engagement patterns across different genres. 

-- Expected Output: 
-- A MySQL database with queries for: 
-- ● Basic: Movies by genre, users by subscription type 

SELECT genre, COUNT(*) AS movie_count
FROM Movies
GROUP BY genre
ORDER BY movie_count DESC;


# users by subscription type 
SELECT plan_type, COUNT(*) AS total_users
FROM Subscriptions
GROUP BY plan_type
ORDER BY total_users DESC;



-- ● Intermediate: Genre-wise watch time, churn segmentation, engagement levels 

#  Genre-wise watch time
SELECT t1.genre , SUM(t2.watch_duration) AS watch_time
FROM movies t1
JOIN watchhistory t2 
ON t1.movie_id = t2.movie_id 
GROUP BY t1.genre
ORDER BY watch_time DESC;

#churn segmentation  ( Users whose subscription ended and not renewed:) 

SELECT 
    u.user_id,
    u.username,
    MAX(s.end_date) AS last_end_date,
    CASE
        WHEN MAX(s.end_date) < CURDATE() THEN 'Churn Risk'
        ELSE 'Active'
    END AS churn_status
FROM Users u
JOIN Subscriptions s 
    ON u.user_id = s.user_id
GROUP BY u.user_id, u.username;

# engagement levels (Based on total watch time:)
SELECT 
    u.user_id,
    u.username,
    COALESCE(SUM(w.watch_duration), 0) AS total_watch_time,
    CASE
        WHEN COALESCE(SUM(w.watch_duration),0) >= 600 THEN 'High'
        WHEN COALESCE(SUM(w.watch_duration),0) BETWEEN 250 AND 599 THEN 'Medium'
        ELSE 'Low'
    END AS engagement_level
FROM Users u
LEFT JOIN WatchHistory w 
    ON u.user_id = w.user_id
GROUP BY u.user_id, u.username;



-- ● Advanced: Movie ranking via window functions, engagement score functions, 
-- monthly watch views 

 # Movie ranking via window functions
 
 SELECT 
    movie_id,
    title,
    avg_rating,
    ROW_NUMBER() OVER (ORDER BY avg_rating DESC) AS rating_rank
FROM (
    SELECT 
        m.movie_id,
        m.title,
        AVG(r.rating) AS avg_rating
    FROM Movies m
    JOIN Reviews r 
        ON m.movie_id = r.movie_id
    GROUP BY m.movie_id, m.title
) t;

SELECT 
    movie_id,
    title,
    avg_rating,
    DENSE_RANK() OVER (ORDER BY avg_rating DESC) AS rating_rank
FROM (
    SELECT 
        m.movie_id,
        m.title,
        AVG(r.rating) AS avg_rating
    FROM Movies m
    JOIN Reviews r 
        ON m.movie_id = r.movie_id
    GROUP BY m.movie_id, m.title
) t;


 
#  engagement score functions

SELECT 
    u.user_id,
    u.username,
    COALESCE(SUM(w.watch_duration),0) AS total_watch,
    COUNT(DISTINCT r.review_id) AS total_reviews,
    COUNT(DISTINCT s.sub_id) AS subs_count,
    ROUND(
        COALESCE(SUM(w.watch_duration),0) * 0.6 +
        COUNT(DISTINCT r.review_id) * 50 +
        COUNT(DISTINCT s.sub_id) * 200,
        2
    ) AS engagement_score
FROM Users u
LEFT JOIN WatchHistory w ON u.user_id = w.user_id
LEFT JOIN Reviews r ON u.user_id = r.user_id
LEFT JOIN Subscriptions s ON u.user_id = s.user_id
GROUP BY u.user_id, u.username;


# monthly watch views 

SELECT 
    DATE_FORMAT(watch_date, '%Y-%m') AS month,
    COUNT(*) AS total_views,
    SUM(watch_duration) AS total_minutes
FROM WatchHistory
GROUP BY month
ORDER BY month;


-- ● Insights on trending movies, churn risk users, and overall engagement. 
# 1)  Trending Movies & Content Performance
-- 21+ movies achieved a perfect average rating of 5, indicating extremely high viewer satisfaction.
-- These top-rated movies should be:
-- promoted on homepage banners
-- featured in recommendation engines
-- used for retention campaigns
-- Genres with high watch time should receive future production investment.

# 2) Genre Popularity & Viewing Behavior
-- Highest total watch time:
-- Genre	Watch Minutes
-- Horror	14,471
-- Drama	12,558
-- Thriller	12,550
-- Documentary	12,483

-- Lowest:
-- Action (7,504 minutes)

-- Horror and Drama are the most engaging genres despite Action having fewer total minutes.
-- Documentary ranking high suggests strong niche audiences
-- Action content may require:
-- better marketing
-- improved quality
-- different sub-genres

# 3) Churn Risk Users
-- 286 users have subscriptions that already ended and were not renewed.
-- Many expirations cluster around mid-2025, suggesting:
-- pricing issues
-- content cycle gaps
-- seasonal churn patterns.

-- These users should be targeted with:
-- win-back email campaigns
-- discounted re-subscription offers
--  recommendations based on favorite genres.

-- Combine churn list with:
-- low engagement
-- no recent watch activity
-- to prioritize high-risk users first.

# 4)  User Engagement Levels
-- From 400 users:
-- Majority fall into Low or Medium engagement.
-- Only a smaller fraction watch heavily.
-- Several users show 0 watch time, meaning:
-- they signed up but never consumed content.

-- Large Low-engagement group = big growth opportunity.
-- Send:
--  onboarding nudges
-- “top 10 movies this week”
-- free previews

-- High-engagement users should be:
--  rewarded with loyalty perks
--  early access content.

# 5)  Monthly Viewing Trends
 -- Observations
-- Month	          Views
-- Mar–Jul2025	   ~130/month peak
-- Sep 2025	    drastic drop (12)


-- Steady viewing Jan–Aug suggests healthy platform activity.
-- Sharp Sep drop may indicate:
-- incomplete data
-- outage
